1	import java.util.List;
2	import java.util.ArrayList;
3	import java.util.Arrays;
4	import java.util.HashMap;
5	import java.util.Iterator;
6	import java.util.Random;
7	
8	/**
9	 * Models a generic disease which can affect organisms and cause them to die
10	 *
11	 * @version 2022.02.28
12	 */
13	public abstract class Disease implements Actor
14	{
15	    // The field of the simulation
16	    private Field field;
17	    // A list of the species that the disease affects
18	    private ArrayList<String> affectedSpecies;
19	    // A hashmap containing organisms currently infected with disease
20	    // and how long they've been infected for
21	    private HashMap<Actor, Integer> affected;
22	    // The probability of the disease randomly occuring in the population
23	    private double probability;
24	    // The probability of the disease spreading
25	    private double infectiousness;
26	    // How long the disease affects an infected organism for
27	    private int duration;
28	    // Randomiser to control random spread of disease
29	    private Random rand = new Random();
30	    
31	    /**
32	     * Constructor for a disease
33	     * 
34	     * @param The field currently occupied
35	     */
36	    public Disease(Field field)
37	    {
38	        this.field = field;
39	        affectedSpecies = new ArrayList<>();
40	        affected = new HashMap<>();
41	        probability = 0.0001;
42	    }
43	
44	    /**
45	     * Make this actor act - that is: disease spreads and kills any 
46	     * infected individuals after a certain number of days
47	     * @param newActors A list to receive any actors relevant to action
48	     */
49	    public void act(List<Actor> actorsList)
50	    {
51	        // Loops through every infected animal
52	        Iterator<Actor> it = affected.keySet().iterator();
53	        // List to hold individuals who are newly infected by disease
54	        ArrayList<Actor> newInfections = new ArrayList<>();
55	        while (it.hasNext()) {
56	            Actor infected = it.next();
57	            newInfections.addAll(spread(infected));
58	            if (affected.get(infected) == duration) {
59	                // After certain number of days, infected individual 
60	                // dies (animal)/ is cured (water)
61	                it.remove();
62	                if (infected instanceof Organism) {
63	                    Organism organism = (Organism) infected;
64	                    organism.setDead();
65	                    }
66	                else {
67	                    WaterSources water = (WaterSources) infected;
68	                    water.notInfected();
69	                }
70	            }
71	            else {
72	                // Increases the number of days an individual has been infected by 1
73	                int days = affected.get(infected) + 1;
74	                affected.put(infected, days);
75	            }
76	        }
77	        for (Actor infectee: newInfections) {
78	            // adds any newly infected individuals to the list and sets days infected to 0
79	            if (infectee instanceof Organism) {
80	                Organism organism = (Organism) infectee;
81	                organism.setInfected();
82	                affected.put(organism, 0);  
83	            }
84	            else if (infectee instanceof WaterSources)  {
85	                WaterSources water = (WaterSources) infectee;
86	                water.setInfected();
87	                affected.put(water, 0);  
88	            }
89	        }
90	    }
91	    
92	    /** 
93	     * Spreads disease to nearby individuals who can be infected
94	     * 
95	     * @param The actor which is infected and spreads disease to 
96	     * neighbouring individuals
97	     */
98	    public ArrayList<Actor> spread(Actor actor) {
99	        ArrayList<Actor> newlyInfected = new ArrayList<>();
100	        List<Location> adjacent = null;
101	        // looks at surrounding individuals and chance of infecting them if possible
102	        try {
103	            Organism organism = (Organism) actor;
104	            if (organism.isAlive()) {
105	                adjacent = field.adjacentLocations(organism.getLocation());
106	            }
107	        } catch (Exception e) {
108	            WaterSources water = (WaterSources) actor;
109	            if (!water.isEmpty()) {
110	                adjacent = field.adjacentLocations(water.getLocation());
111	            }
112	        }
113	        if(adjacent != null) {
114	            Iterator<Location> it = adjacent.iterator();
115	            while(it.hasNext()) {
116	                Location where = it.next();
117	                Object thing = field.getObjectAt(where);
118	                if (thing != null && affectedSpecies.contains(thing.getClass().getName())) {
119	                    if (rand.nextDouble() < infectiousness) {
120	                        if (thing instanceof Organism) {
121	                            Organism infectee = (Organism) thing;
122	                            newlyInfected.add(infectee);
123	                        }
124	                        else if (thing instanceof WaterSources) {
125	                            WaterSources infectee = (WaterSources) thing;
126	                            newlyInfected.add(infectee);
127	                        }
128	                    }
