/**
 * Headless smoke test for the refactor. Exercises the model classes (no GUI)
 * over a seeded scenario and reports a population signature. Running it twice
 * with Randomizer.reset() in between must yield identical signatures now that
 * all randomness flows through the shared, seeded Randomizer.
 */
public class Harness
{
    private static String runOnce()
    {
        Randomizer.reset();
        Random rand = Randomizer.getRandom();
        Field field = new Field(40, 40);
        List<Actor> actors = new ArrayList<>();

        // Seeded population, mirroring Simulator.populate's style.
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Location loc = new Location(row, col);
                double r = rand.nextDouble();
                if (r <= 0.02)      actors.add(new Lion(true, field, loc));
                else if (r <= 0.04) actors.add(new Hyena(true, field, loc));
                else if (r <= 0.06) actors.add(new Gazelle(true, field, loc));
                else if (r <= 0.08) actors.add(new Mouse(true, field, loc));
                else if (r <= 0.10) actors.add(new FennecFox(true, field, loc));
                else if (r <= 0.30) actors.add(new Grass(true, field, loc));
            }
        }

        // Mini simulation loop (no Weather/Disease — those need the Simulator).
        for (int step = 0; step < 40; step++) {
            List<Actor> newborns = new ArrayList<>();
            List<Actor> next = new ArrayList<>();
            for (Actor a : actors) {
                Organism o = (Organism) a;
                if (o.isAlive()) {
                    a.act(newborns);
                }
                if (((Organism) a).isAlive()) {
                    next.add(a);
                }
            }
            next.addAll(newborns);
            actors = next;
        }

        TreeMap<String, Integer> counts = new TreeMap<>();
        for (Actor a : actors) {
            String name = a.getClass().getSimpleName();
            counts.merge(name, 1, Integer::sum);
        }
        return counts.toString();
    }

    public static void main(String[] args)
    {
        String first = runOnce();
        String second = runOnce();
        System.out.println("Run 1: " + first);
        System.out.println("Run 2: " + second);
        System.out.println(first.equals(second)
            ? "DETERMINISTIC: signatures match across seeded reset."
            : "NON-DETERMINISTIC: signatures differ!");
    }
}

